class OpenNavigationRecordsEvaluator(BaseEvaluator):
    """Verify the saved routes and incident reports the instruction asks for.

    Each declared route must be present exactly once among the records the
    application persisted, and each declared report likewise.  A machine where
    the task was not carried out holds no such records, which is a failure.
    """

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        state = read_opennavigation_state(
            context.get("controller"),
            profile_dir=str(params.get("profile_dir") or DEFAULT_PROFILE_DIR),
            user_email=str(params.get("user_email") or DEFAULT_USER),
            timeout=float(params.get("timeout", 20) or 20),
        )
        routes = _route_rows(state)
        reports = _report_rows(state)

        checks: list[dict[str, Any]] = []
        for expected_raw in params.get("expected_routes") or []:
            expected = dict(expected_raw)
            matched = [row for row in routes if _matches(expected, row)[0]]
            checks.append({
                "check_id": f"route:{expected.get('name')}",
                "passed": len(matched) == 1,
                "expected": expected,
                "observed_count": len(matched),
            })
        for expected_raw in params.get("expected_reports") or []:
            expected = dict(expected_raw)
            matched = [row for row in reports if _matches(expected, row)[0]]
            checks.append({
                "check_id": f"report:{expected.get('note') or expected.get('type')}",
                "passed": len(matched) == 1,
                "expected": expected,
                "observed_count": len(matched),
            })

        profile_ok = bool(state.get("profile_exists"))
        passed = bool(checks) and profile_ok and all(item["passed"] for item in checks)
        failed = [item["check_id"] for item in checks if not item["passed"]]
        metadata = {
            "checks": checks,
            "failures": failed,
            "profile_exists": profile_ok,
            "record_counts": {key: len(value) for key, value in (state.get("records") or {}).items()},
            "source_state_mode": "read_only",
        }
        if not passed:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenNavigation does not hold the required records: " + ", ".join(failed or ["profile"]),
                metadata=metadata,
            )
        return EvalResult(status=EvalStatus.PASS, message="OpenNavigation holds every required record", metadata=metadata)


# Reads the visible text of the OpenNavigation web page through the guest
# Chrome's DevTools endpoint (``Runtime.evaluate`` of ``innerText`` only; it
# never navigates or changes the page).  Standard library only.
_BROWSER_TEXT_PROGRAM = r'''
import base64, json, os, socket, struct, urllib.request
from urllib.parse import urlparse

PORT = __PORT__
MATCH = __MATCH__


def ws_eval(ws_url, expression, timeout=8.0):
    parsed = urlparse(ws_url)
    sock = socket.create_connection((parsed.hostname, parsed.port or 80), timeout=timeout)
    try:
        key = base64.b64encode(os.urandom(16)).decode()
        sock.sendall((
            "GET %s HTTP/1.1\r\nHost: %s:%s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
            "Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n\r\n"
            % (parsed.path, parsed.hostname, parsed.port, key)
        ).encode())
        buf = b""
        while b"\r\n\r\n" not in buf:
            chunk = sock.recv(4096)
            if not chunk:
                raise OSError("websocket handshake closed")
            buf += chunk
        head, buf = buf.split(b"\r\n\r\n", 1)
        if b" 101 " not in head.split(b"\r\n")[0] + b" ":
            raise OSError("websocket handshake refused")
        payload = json.dumps({"id": 1, "method": "Runtime.evaluate",
                              "params": {"expression": expression, "returnByValue": True}}).encode()
        mask = os.urandom(4)
        header = bytearray([0x81])
        if len(payload) < 126:
            header.append(0x80 | len(payload))
        elif len(payload) < 65536:
            header += bytes([0x80 | 126]) + struct.pack(">H", len(payload))
        else:
            header += bytes([0x80 | 127]) + struct.pack(">Q", len(payload))
        sock.sendall(bytes(header) + mask + bytes(b ^ mask[i % 4] for i, b in enumerate(payload)))
        state = {"buf": buf}

        def read(count):
            while len(state["buf"]) < count:
                chunk = sock.recv(65536)
                if not chunk:
                    raise OSError("websocket closed")
                state["buf"] += chunk
            out, state["buf"] = state["buf"][:count], state["buf"][count:]
            return out

        message = b""
        while True:
            first, second = read(2)
            length = second & 0x7F
            if length == 126:
                length = struct.unpack(">H", read(2))[0]
            elif length == 127:
                length = struct.unpack(">Q", read(8))[0]
            if second & 0x80:
                read(4)
            data = read(length)
            opcode = first & 0x0F
            if opcode == 0x8:
                raise OSError("websocket closed by peer")
            if opcode not in (0x0, 0x1):
                continue
            message += data
            if not first & 0x80:
                continue
            reply = json.loads(message.decode("utf-8", "replace"))
            message = b""
            if reply.get("id") == 1:
                return ((reply.get("result") or {}).get("result") or {}).get("value")
    finally:
        sock.close()


result = {"pages": [], "errors": []}
try:
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    with opener.open("http://127.0.0.1:%d/json/list" % PORT, timeout=5) as response:
        pages = json.loads(response.read().decode("utf-8", "replace"))
except Exception as exc:
    pages = []
    result["errors"].append("devtools list: %s" % exc)
for page in pages:
    if page.get("type") != "page" or not page.get("webSocketDebuggerUrl"):
        continue
    hay = ("%s %s" % (page.get("url") or "", page.get("title") or "")).lower()
    if MATCH and not any(term.lower() in hay for term in MATCH):
        continue
    try:
        value = ws_eval(page["webSocketDebuggerUrl"], "document.body ? document.body.innerText : ''")
    except Exception as exc:
        result["errors"].append("%s: %s" % (page.get("url"), exc))
        continue
    result["pages"].append({"url": page.get("url"), "title": page.get("title"),
                            "text": str(value or "")[:200000]})
print(json.dumps(result, ensure_ascii=False))
'''

DEFAULT_BROWSER_URL_TERMS = ("127.0.0.1:4321", "localhost:4321", "opennavigation")


def _browser_page_text(controller: Any, params: Mapping[str, Any]) -> dict[str, Any]:
    """Return the text of the OpenNavigation pages open in the guest Chrome."""
    if controller is None or not hasattr(controller, "run_python_script"):
        return {"pages": [], "errors": ["no guest controller"]}
    terms = params.get("browser_url_terms") or list(DEFAULT_BROWSER_URL_TERMS)
    program = (
        _BROWSER_TEXT_PROGRAM.replace("__PORT__", str(int(params.get("devtools_port", 1337) or 1337)))
        .replace("__MATCH__", json.dumps([str(term) for term in terms]))
    )
    try:
        raw = controller.run_python_script(program, timeout=int(params.get("timeout", 20) or 20) + 10)
        text = str(raw.get("stdout") or raw.get("output") or "").strip()
        parsed = json.loads(text.splitlines()[-1])
    except Exception as exc:  # noqa: BLE001 - the page is an optional evidence source
        return {"pages": [], "errors": ["devtools read: %s" % exc]}
    return dict(parsed) if isinstance(parsed, Mapping) else {"pages": [], "errors": ["bad devtools reply"]}


class OpenNavigationRouteReviewEvaluator(BaseEvaluator):
    """Verify that a route review left the expected vocabulary in the app.

    The required terms must be present in what the application persisted or in
    the final observation, and none of the forbidden terms may be.
    """

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        state = read_opennavigation_state(
            context.get("controller"),
            profile_dir=str(params.get("profile_dir") or DEFAULT_PROFILE_DIR),
            user_email=str(params.get("user_email") or DEFAULT_USER),
            timeout=float(params.get("timeout", 20) or 20),
        )
        rows = _route_rows(state) + _report_rows(state)
        corpus = _record_text(rows)
        observation = context.get("final_observation")
        for node in getattr(observation, "ui_nodes", []) or []:
            if isinstance(node, Mapping):
                corpus += " " + str(node.get("text") or "")
        browser = _browser_page_text(context.get("controller"), params)
        for page in browser.get("pages") or []:
            corpus += " " + str(page.get("text") or "")

        required = [str(term) for term in params.get("required_terms") or []]
        forbidden = [str(term) for term in params.get("forbidden_terms") or []]
        checks = [
            {"check_id": f"required:{term}", "passed": term in corpus}
            for term in required
        ] + [
            {"check_id": f"forbidden:{term}", "passed": term not in corpus}
            for term in forbidden
        ]
        failed = [item["check_id"] for item in checks if not item["passed"]]
        metadata = {
            "checks": checks,
            "failures": failed,
            "record_count": len(rows),
            "browser_pages": [
                {"url": page.get("url"), "title": page.get("title"), "text_length": len(str(page.get("text") or ""))}
                for page in browser.get("pages") or []
            ],
            "browser_errors": list(browser.get("errors") or [])[:5],
            "read_only": True,
        }
        if not required or failed:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenNavigation route review is incomplete: " + ", ".join(failed or ["no required terms declared"]),
                metadata=metadata,
            )
        return EvalResult(status=EvalStatus.PASS, message="OpenNavigation route review vocabulary verified", metadata=metadata)


class OpenNavigationWorkflowEvaluator(BaseEvaluator):
    """Verify the map-layer state a navigation workflow is expected to leave."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        expected_state = str(params.get("expected_final_state") or "")
        observation = context.get("final_observation")
        nodes = [dict(node) for node in (getattr(observation, "ui_nodes", []) or []) if isinstance(node, Mapping)]
        texts = [str(node.get("text") or "") for node in nodes]
        corpus = " ".join(texts)

        terms = [term for term in expected_state.split("_") if len(term) > 2]
        foreground = str(getattr(observation, "foreground_app", "") or "")
        checks = [
            {"check_id": "window_is_opennavigation", "passed": foreground == "OpenNavigation"},
            {
                "check_id": "final_state_visible",
                "passed": bool(texts) and all(term.lower() in corpus.lower() for term in terms),
            },
        ]
        failed = [item["check_id"] for item in checks if not item["passed"]]
        metadata = {
            "checks": checks,
            "failures": failed,
            "expected_final_state": expected_state,
            "observed_text_count": len(texts),
            "foreground_app": foreground,
            "read_only": True,
        }
        if failed:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenNavigation final map state is not the expected one: " + ", ".join(failed),
                metadata=metadata,
            )
        return EvalResult(status=EvalStatus.PASS, message="OpenNavigation final map state verified", metadata=metadata)
